import math, re
from collections import Counter
from messages import train, test

def words(text):
    return re.findall(r"[a-z]+", text.lower())

# Training: count how often each word appears in spam and in normal messages
counts = {1: Counter(), 0: Counter()}
docs = Counter()
for text, label in train:
    counts[label].update(words(text))
    docs[label] += 1
vocab = set(counts[1]) | set(counts[0])

def p_word(word, label):
    # add-one smoothing: a word never seen in this class still gets a small chance
    return (counts[label][word] + 1) / (sum(counts[label].values()) + len(vocab))

def spam_probability(text):
    log_score = {}
    for label in (1, 0):
        log_score[label] = math.log(docs[label] / len(train))
        for w in words(text):
            log_score[label] += math.log(p_word(w, label))
    # turn the two scores back into a probability between 0 and 1
    top = max(log_score.values())
    s, h = math.exp(log_score[1] - top), math.exp(log_score[0] - top)
    return s / (s + h)

if __name__ == "__main__":
    print(f"trained on {len(train)} messages, {len(vocab)} different words")
    spammy = sorted(vocab, key=lambda w: p_word(w, 1) / p_word(w, 0), reverse=True)[:6]
    print("most spam-like words:", ", ".join(spammy))

    correct = 0
    for text, label in test:
        p = spam_probability(text)
        guess = 1 if p > 0.5 else 0
        correct += guess == label
        print(f"{p:6.3f}  {'SPAM' if guess else 'ok  '}  {'right' if guess == label else 'WRONG'}  {text}")
    print(f"test accuracy: {correct} of {len(test)}")

import re
from collections import Counter
from messages import train

counts = {1: Counter(), 0: Counter()}
for text, label in train:
    counts[label].update(re.findall(r"[a-z]+", text.lower()))
vocab = set(counts[1]) | set(counts[0])

def p_raw(word, label):          # no smoothing
    return counts[label][word] / sum(counts[label].values())

def p_smooth(word, label):       # add-one smoothing
    return (counts[label][word] + 1) / (sum(counts[label].values()) + len(vocab))

message = "click here to claim your free prize for your homework"
for name, p in [("without smoothing", p_raw), ("with smoothing", p_smooth)]:
    spam = ham = 0.5
    for w in message.split():
        spam *= p(w, 1)
        ham *= p(w, 0)
    verdict = "SPAM" if spam > ham else "ok"
    print(f"{name:<18} spam score {spam:.3g}  normal score {ham:.3g}  -> {verdict}")
print("'homework' seen in spam:", counts[1]["homework"], "times")
